17	// fakeCrow with two versions of moduleA. v1 has main.tf; v2 has main.tf
18	// (modified) and a new variables.tf.
19	func fakeCrowTwoVersions(t *testing.T) *httptest.Server {
20		t.Helper()
21		mkTgz := func(files map[string]string) []byte {
22			var buf bytes.Buffer
23			gz := gzip.NewWriter(&buf)
24			tw := tar.NewWriter(gz)
25			for n, b := range files {
26				_ = tw.WriteHeader(&tar.Header{Name: n, Mode: 0o644, Size: int64(len(b)), Typeflag: tar.TypeReg})
27				_, _ = tw.Write([]byte(b))
28			}
29			_ = tw.Close()
30			_ = gz.Close()
31			return buf.Bytes()
32		}
33		v1 := mkTgz(map[string]string{"main.tf": "resource \"aws_s3_bucket\" \"alpha\" {}\n"})
34		v2 := mkTgz(map[string]string{
35			"main.tf":      "resource \"aws_s3_bucket\" \"beta\" {}\n",
36			"variables.tf": "variable \"name\" { type = string }\n",
37		})
38	
39		mux := http.NewServeMux()
40		blob := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
41			switch r.URL.Path {
42			case "/blob/1.0.0":
43				_, _ = w.Write(v1)
44			case "/blob/1.1.0":
45				_, _ = w.Write(v2)
46			default:
47				http.NotFound(w, r)
48			}
49		}))
50		t.Cleanup(blob.Close)
51		mux.HandleFunc("/v1/modules/iac/comply/aws/", func(w http.ResponseWriter, r *http.Request) {
52			parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/v1/modules/iac/comply/aws/"), "/")
53			if len(parts) != 2 || parts[1] != "download" {
54				http.NotFound(w, r)
55				return
56			}
57			w.Header().Set("X-Terraform-Get", blob.URL+"/blob/"+parts[0])
58			w.WriteHeader(http.StatusNoContent)
59		})
60		srv := httptest.NewServer(mux)
61		t.Cleanup(srv.Close)
62		return srv
63	}
