65	func TestDiffPlainOutput(t *testing.T) {
66		srv := fakeCrowTwoVersions(t)
67		root := NewRootCmd()
68		var stdout, stderr bytes.Buffer
69		root.SetOut(&stdout)
70		root.SetErr(&stderr)
71		root.SetArgs([]string{
72			"diff",
73			"iac/comply/aws", "1.0.0", "1.1.0",
74			"--crow-url", srv.URL,
75			"--plain",
76			"--cache-dir", t.TempDir(),
77		})
78		if err := root.ExecuteContext(context.Background()); err != nil {
79			t.Fatalf("execute: %v\nstderr: %s", err, stderr.String())
80		}
81		out := stdout.String()
82		for _, want := range []string{"main.tf", "variables.tf", "alpha", "beta"} {
83			if !strings.Contains(out, want) {
84				t.Errorf("plain output missing %q\n--- output ---\n%s", want, out)
85			}
86		}
87	}
